(147699, 7529, 4648, '<td valign="top">Good balancing act of the chair.  The stuffed animal makes it for the illusion.  Good job.  Good picture.</td>', 'Good balancing act of the chair.  The stuffed animal makes it for the illusion.  Good job.  Good picture.', '2002-10-29 23:47:00.000000', NULL, 1),
(147700, 7529, 4615, '<td valign="top">good shot: 8 for technical/execution  9 for humor/over all concept 6 for meeting challenge criteria (it shows skill not illusion, unless the hippo is meant to be counterbalancing him.)  Good luck.</td>', 'good shot: 8 for technical/execution  9 for humor/over all concept 6 for meeting challenge criteria (it shows skill not illusion, unless the hippo is meant to be counterbalancing him.)  Good luck.', '2002-10-30 08:20:00.000000', NULL, 1),
