(148097, 7579, 3540, '<td valign="top">The idea works, but the photo is just generally blurry.  It''s hard to give a good score to something like this.  I think you could''ve made it work if it were done a little better. - Inspzil</td>', 'The idea works, but the photo is just generally blurry.  It''s hard to give a good score to something like this.  I think you could''ve made it work if it were done a little better. - Inspzil', '2002-10-29 08:05:00.000000', NULL, 1),
(148098, 7579, 2295, '<td valign="top">Nice shot.  The monster being out of focus is a bit distracting.  The child did a good job of being afraid.  Lighting is good.  Meets the subject matter.  7 waltom.</td>', 'Nice shot.  The monster being out of focus is a bit distracting.  The child did a good job of being afraid.  Lighting is good.  Meets the subject matter.  7 waltom.', '2002-10-30 10:06:00.000000', NULL, 1),
(148099, 7579, 4648, '<td valign="top">How did you ever get the cute kid to pose for you.  To the photo.  Monster out of focus and kids hand way out of focus.  Focus of kid a little soft rest fairly sharp.</td>', 'How did you ever get the cute kid to pose for you.  To the photo.  Monster out of focus and kids hand way out of focus.  Focus of kid a little soft rest fairly sharp.', '2002-10-30 10:18:00.000000', NULL, 1),
(148100, 7579, 1005, '<td valign="top">Very cute!  Might need acting lessons, ha, ha, but I do like the hand motion.  Cool.<br/>8 Swash</td>', 'Very cute!  Might need acting lessons, ha, ha, but I do like the hand motion.  Cool.8 Swash', '2002-10-31 19:24:00.000000', NULL, 1),
(148101, 7579, 472, '<td valign="top">i like the expression on the kid''s face. the fact that the monster is blurred blows the illusion as it''s a giveaway that it''s closer to the camera.  mag99</td>', 'i like the expression on the kid''s face. the fact that the monster is blurred blows the illusion as it''s a giveaway that it''s closer to the camera.  mag99', '2002-11-01 12:47:00.000000', NULL, 1),
(148102, 7579, 4275, '<td valign="top">wow great photo the best ive seen yet 1</td>', 'wow great photo the best ive seen yet 1', '2002-11-02 19:42:00.000000', NULL, 1),
