INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(148104, 7581, 4536, '<td valign="top">would have been a bit stronger if your hand was in focus too.</td>', 'would have been a bit stronger if your hand was in focus too.', '2002-10-28 12:22:00.000000', NULL, 1),
(148105, 7581, 4430, '<td valign="top">it fits the challenge but the hand really has to be in focus to make this work.</td>', 'it fits the challenge but the hand really has to be in focus to make this work.', '2002-10-28 18:35:00.000000', NULL, 1),
(148106, 7581, 2866, '<td valign="top">This shot had real potential, but you needed to find a better location.</td>', 'This shot had real potential, but you needed to find a better location.', '2002-10-28 19:04:00.000000', NULL, 1),
(148107, 7581, 3546, '<td valign="top">This would have worked better for me if the sign board wasn''t beneath your hand,.</td>', 'This would have worked better for me if the sign board wasn''t beneath your hand,.', '2002-10-29 08:31:00.000000', NULL, 1),
(148108, 7581, 772, '<td valign="top">I understand your illusion, but the ''wow'' factor on this photo is minimal... in this particular photo, the focus is quite soft throughout the image... some of the surroundings here could be considered distracting and ''busy'' as well... - setzler</td>', 'I understand your illusion, but the ''wow'' factor on this photo is minimal... in this particular photo, the focus is quite soft throughout the image... some of the surroundings here could be considered distracting and ''busy'' as well... - setzler', '2002-10-29 10:48:00.000000', NULL, 1),
(148109, 7581, 4648, '<td valign="top">I think this is the first trick photo every child tries with their first camera.  You did a super job of keeping every thing if approximately same focus.  Not real clear but not that bad either.  Shame hand not clearer.</td>', 'I think this is the first trick photo every child tries with their first camera.  You did a super job of keeping every thing if approximately same focus.  Not real clear but not that bad either.  Shame hand not clearer.', '2002-10-29 23:30:00.000000', NULL, 1),
(148110, 7581, 4615, '<td valign="top">Should have made sure no part of the sign was covered by the hand.</td>', 'Should have made sure no part of the sign was covered by the hand.', '2002-10-30 08:56:00.000000', NULL, 1),
(148111, 7581, 2158, '<td valign="top">The illusion is not totally successful because of the cut off corner on the left.</td>', 'The illusion is not totally successful because of the cut off corner on the left.', '2002-10-30 18:24:00.000000', NULL, 1),
(148112, 7581, 1005, '<td valign="top">To me, the hand needed to be in focus rather than the sign.  Points for having an illusion present.  7 Swash</td>', 'To me, the hand needed to be in focus rather than the sign.  Points for having an illusion present.  7 Swash', '2002-10-30 19:26:00.000000', NULL, 1),
(148113, 7581, 2752, '<td valign="top">good attempt of the sense of scales.</td>', 'good attempt of the sense of scales.', '2002-10-30 23:07:00.000000', NULL, 1),
(148114, 7581, 2472, '<td valign="top">As you might have found out, the hard part in this kind of shot is the focus of two distant planes (the hand and the sign), this can be achived by configuring the lens aperture and the exposition time, in order to flatten the planes and being able to get both in focus.</td>', 'As you might have found out, the hard part in this kind of shot is the focus of two distant planes (the hand and the sign), this can be achived by configuring the lens aperture and the exposition time, in order to flatten the planes and being able to get both in focus.', '2002-10-31 12:07:00.000000', NULL, 1),
(148115, 7582, 3540, '<td valign="top">I think the focus on this one was on the tips of the right hand''s fingers.  This illusion boggled me as a kid too.  - Inspzil</td>', 'I think the focus on this one was on the tips of the right hand''s fingers.  This illusion boggled me as a kid too.  - Inspzil', '2002-10-28 05:09:00.000000', NULL, 1),
(148116, 7582, 2527, '<td valign="top">more light will help... good idea!<br/>good luck!<br/>Richi</td>', 'more light will help... good idea!good luck!Richi', '2002-10-28 08:40:00.000000', NULL, 1),
(148117, 7582, 2567, '<td valign="top">I like the composition and I think B&amp;W works very well.</td>', 'I like the composition and I think B&W works very well.', '2002-10-28 11:24:00.000000', NULL, 1),
(148118, 7582, 2044, '<td valign="top">needs a little more light</td>', 'needs a little more light', '2002-10-28 11:37:00.000000', NULL, 1),
(148119, 7582, 4517, '<td valign="top">another one. not bad</td>', 'another one. not bad', '2002-10-28 12:34:00.000000', NULL, 1),
(148120, 7582, 2792, '<td valign="top">Love the title.  Certainly is a father''s trick ;-)  8/10</td>', 'Love the title.  Certainly is a father''s trick ;-)  8/10', '2002-10-28 15:55:00.000000', NULL, 1),
(148121, 7582, 4077, '<td valign="top">Erk... same concept as mine. Although, I''d have to confess that this is a better shot. seasick - 7</td>', 'Erk... same concept as mine. Although, I''d have to confess that this is a better shot. seasick - 7', '2002-10-28 16:09:00.000000', NULL, 1),
(148122, 7582, 327, '<td valign="top">lol Fun. Nice job.</td>', 'lol Fun. Nice job.', '2002-10-28 16:40:00.000000', NULL, 1),
(148123, 7582, 2716, '<td valign="top">How d''you do that?  ha ha! 6. A little blurry.</td>', 'How d''you do that?  ha ha! 6. A little blurry.', '2002-10-28 17:26:00.000000', NULL, 1),
(148124, 7582, 4648, '<td valign="top">Who hasn''t done this illusion for their child or grandchild.  But good picture.  Very clear of hand  Could use a little more light on the "illusioned thumb.  It''s a little behind the hand therefore a little darker.</td>', 'Who hasn''t done this illusion for their child or grandchild.  But good picture.  Very clear of hand  Could use a little more light on the "illusioned thumb.  It''s a little behind the hand therefore a little darker.', '2002-10-28 18:12:00.000000', NULL, 1),
(148125, 7582, 4482, '<td valign="top">Nice use of light. Too bad the focus is are on the 2 outstretched fingers and... oops, I see a part of your thumb on the other side.  7</td>', 'Nice use of light. Too bad the focus is are on the 2 outstretched fingers and... oops, I see a part of your thumb on the other side.  7', '2002-10-28 18:34:00.000000', NULL, 1),
