(148127, 7582, 1005, '<td valign="top">This seems to be a favorite "dad" trick!  Well done!  Thank you for blanking out the background, so the attention is focused on the "trick".  7 Swash</td>', 'This seems to be a favorite "dad" trick!  Well done!  Thank you for blanking out the background, so the attention is focused on the "trick".  7 Swash', '2002-10-28 19:50:00.000000', NULL, 1),
