(148151, 7583, 1255, '<td valign="top">My favorite of the week.  A classy well done illusion and an interesting shot to look at to boot.  shedonsit 10</td>', 'My favorite of the week.  A classy well done illusion and an interesting shot to look at to boot.  shedonsit 10', '2002-10-29 23:33:00.000000', NULL, 1),
(148152, 7583, 4615, '<td valign="top">There are so great hand portrates this week.  Reveals lots of detail and character.  8 for technical, 8 for composition, 3 for challenge</td>', 'There are so great hand portrates this week.  Reveals lots of detail and character.  8 for technical, 8 for composition, 3 for challenge', '2002-10-30 08:47:00.000000', NULL, 1),
