(148481, 7613, 4411, '<td valign="top">Not so much an illusion, but a very nice photo.<br/>How many times did you burn yourself doing this?</td>', 'Not so much an illusion, but a very nice photo.How many times did you burn yourself doing this?', '2002-10-28 08:47:00.000000', NULL, 1),
(148482, 7613, 917, '<td valign="top">you could have put the flame behind the hand, eliminating the match altogether. As this is, its not really an illusion, just someone holding a match. Good clarity on the photo. Its also a candidate for rule of thirds, with thumb and flame being on lines of thirds.</td>', 'you could have put the flame behind the hand, eliminating the match altogether. As this is, its not really an illusion, just someone holding a match. Good clarity on the photo. Its also a candidate for rule of thirds, with thumb and flame being on lines of thirds.', '2002-10-28 12:32:00.000000', NULL, 1),
(148483, 7613, 4517, '<td valign="top">its a nice sharp photo but it would be a better illusion if you couldn`t see the match</td>', 'its a nice sharp photo but it would be a better illusion if you couldn`t see the match', '2002-10-28 16:01:00.000000', NULL, 1),
(148484, 7613, 327, '<td valign="top">ouchie......! neat shot. justine 8</td>', 'ouchie......! neat shot. justine 8', '2002-10-28 16:06:00.000000', NULL, 1),
