(149558, 7701, 3575, '<td valign="top">Yeah! I absolutely love thei photograph! You did an incredible job. Congratulations!</td>', 'Yeah! I absolutely love thei photograph! You did an incredible job. Congratulations!', '2002-11-04 11:46:00.000000', NULL, 0),
(149559, 7701, 4564, '<td valign="top">I think it shows that this image was computer generated.  Maybe it`s a photo of a computer generated image.  Still, the jagged edges show taht it was computer generated...</td>', 'I think it shows that this image was computer generated.  Maybe it`s a photo of a computer generated image.  Still, the jagged edges show taht it was computer generated...', '2002-11-05 16:36:00.000000', NULL, 0),
(149560, 7701, 3686, '<td valign="top">i believe it is computer generated as well.</td>', 'i believe it is computer generated as well.', '2002-11-06 20:32:00.000000', NULL, 0),
(149561, 7701, 4708, '<td valign="top">The shading on the underside of the white King seems to be an inconsistent lighting angle  with the shadows on the board.  Additionally, the depth of the board (the blue frame), is the exact same number of pixels at the far end of the board as it is at the near end, which would be a strange thing to naturally occur given the perspective.  I agree this is probably a photo of a computer generated image being displayed on a screen.</td>', 'The shading on the underside of the white King seems to be an inconsistent lighting angle  with the shadows on the board.  Additionally, the depth of the board (the blue frame), is the exact same number of pixels at the far end of the board as it is at the near end, which would be a strange thing to naturally occur given the perspective.  I agree this is probably a photo of a computer generated image being displayed on a screen.', '2002-11-07 02:50:00.000000', NULL, 0),
(149562, 7701, 2223, '<td valign="top">Tim, are you going to explain how this was done?</td>', 'Tim, are you going to explain how this was done?', '2002-11-07 15:15:00.000000', NULL, 0),
